package glitch

import data.glitch_lib

secure_flag_patterns := {"ssl", "tls", "https", "encrypt", "certificate", "cert", "secure", "enforce", "min_tls_version", "ssl_mode", "ssl_policy", "force_https", "enable_https_traffic_only", "validate_certs"}

check_disabled_secure_flag(name, value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    regex.match("false|disabled|no", value.value)
} else {
    value.ir_type == "String"
    name == "protocol"
    value.value == "http"
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [path, n])
    n.ir_type == "String"
    glitch_lib.traverse(n, "http://")
    result := {
        "type": "sec_https",
        "element": n,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - String value contains unencrypted URL (HTTP). (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [path, n])
    (n.ir_type == "Attribute" or n.ir_type == "Variable")
    regex.match(sprintf("(?i).*(%s).*", [concat("|", secure_flag_patterns)]), n.name)
    check_disabled_secure_flag(n.name, n.value)
    result := {
        "type": "sec_https",
        "element": n,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Secure flag disabled or insecure protocol configured. (CWE-319)"
    }
}
